import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Set up Bedrock packs","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/setup.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/setup.md","filePath":"packages/bedrock-addon-manager/docs/setup.md","lastUpdated":1792252144000}`),a={name:`packages/bedrock-addon-manager/docs/setup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="set-up-bedrock-packs" tabindex="-1">Set up Bedrock packs <a class="header-anchor" href="#set-up-bedrock-packs" aria-label="Permalink to “Set up Bedrock packs”">​</a></h1><h2 id="install-and-scan-packs" tabindex="-1">Install and scan packs <a class="header-anchor" href="#install-and-scan-packs" aria-label="Permalink to “Install and scan packs”">​</a></h2><ol><li>Put <code>bedrock-addon-manager.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory.</li><li>Start or restart the server. When prompted, grant <code>fs.read.data</code>, <code>fs.write.data</code>, and <code>network.tcp.bind</code> so the plugin can read packs, create its config and extracted files, and serve downloads.</li><li>Copy <code>.mcpack</code> or <code>.mcaddon</code> files into <code>plugins/data/BedrockAddonManager/packs/</code>.</li><li>Run <code>/baddon reload</code>, then <code>/baddon list</code> to inspect the packs and their effective settings.</li></ol><p>BedrockAddonManager scans the folder at startup and whenever you run <code>/baddon reload</code>, so it won&#39;t pick up new files automatically. It creates and updates its own <code>config.toml</code> in the data folder; configuration changes take effect after a reload or server restart.</p><h2 id="choose-a-download-address" tabindex="-1">Choose a download address <a class="header-anchor" href="#choose-a-download-address" aria-label="Permalink to “Choose a download address”">​</a></h2><p>The built-in server listens on <code>web.bind</code> and <code>web.port</code> (default <code>0.0.0.0:8123</code>). Choose a URL that Bedrock clients can reach:</p><ul><li>If a reverse proxy or external host serves the files, set <code>web.public_url</code> to the base URL clients should use. Don&#39;t add a trailing slash. The built-in server uses plain HTTP, so terminate HTTPS at the proxy.</li><li>To use UPnPumpkin port forwarding, leave <code>web.public_url</code> empty, keep <code>web.bind</code> at <code>0.0.0.0</code>, and enable <code>web.port_forwarding</code>. This requires a router that allows port mapping; it won&#39;t work behind carrier-grade NAT.</li><li>Set <code>web.port_forwarding = false</code> when forwarding is managed manually.</li><li>If packs are hosted elsewhere, set <code>web.enabled = false</code> and provide a <code>download_url</code> override for every enabled pack.</li></ul><p>If forwarding doesn&#39;t succeed and you haven&#39;t set a public URL, the plugin gives clients a loopback address. That address works only on the server machine.</p><h2 id="mcaddon-bundles-and-overrides" tabindex="-1"><code>.mcaddon</code> bundles and overrides <a class="header-anchor" href="#mcaddon-bundles-and-overrides" aria-label="Permalink to “.mcaddon bundles and overrides”">​</a></h2><p>The plugin extracts resource packs from bundles into <code>packs/.extracted/</code> and leaves behavior packs out. When a bundle contains one resource pack, its extracted filename follows the bundle name; if it contains several, each filename also includes the pack name. Use the exact effective filename shown by <code>/baddon list</code> as the key under <code>overrides</code>.</p><p>You can use <code>overrides</code> to change pack order, disable a pack, provide a different download URL, or set manifest values such as <code>content_key</code> and <code>content_id</code>. Packs are ordered by <code>order</code>, then by filename. The plugin doesn&#39;t edit the server&#39;s <code>pumpkin.toml</code>.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};